ALTER TYPE "DeviceProtocol" ADD VALUE IF NOT EXISTS 'MODBUS_RTU';
ALTER TYPE "DeviceProtocol" ADD VALUE IF NOT EXISTS 'MODBUS_TCP';
ALTER TYPE "DeviceProtocol" ADD VALUE IF NOT EXISTS 'PULSE';
CREATE TYPE "ProtocolMode" AS ENUM ('POLLING','EVENT');
CREATE TYPE "SecurityMode" AS ENUM ('NONE','OMS_AES128','TLS','API_KEY','OAUTH2');
ALTER TABLE "Device" ADD COLUMN "profileId" TEXT, ADD COLUMN "protocolConfig" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "protocolMode" "ProtocolMode" NOT NULL DEFAULT 'POLLING';
CREATE TABLE "DeviceProfile" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"manufacturer" TEXT NOT NULL,"model" TEXT NOT NULL,"utility" "MeterType" NOT NULL,"protocol" "DeviceProtocol" NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"capabilities" JSONB NOT NULL,"mapping" JSONB NOT NULL,"defaults" JSONB NOT NULL DEFAULT '{}',"firmwareNotes" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "DeviceProfile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DeviceProfile_id_tenantId_key" ON "DeviceProfile"("id","tenantId");
CREATE UNIQUE INDEX "DeviceProfile_tenantId_manufacturer_model_version_key" ON "DeviceProfile"("tenantId","manufacturer","model","version");
CREATE INDEX "DeviceProfile_tenantId_utility_protocol_idx" ON "DeviceProfile"("tenantId","utility","protocol");
ALTER TABLE "DeviceProfile" ADD CONSTRAINT "DeviceProfile_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Device" ADD CONSTRAINT "Device_profileId_tenantId_fkey" FOREIGN KEY ("profileId","tenantId") REFERENCES "DeviceProfile"("id","tenantId") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "PulseConfig" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"impulsesPerUnit" DECIMAL(20,6) NOT NULL,"unit" TEXT NOT NULL,"utility" "MeterType" NOT NULL,"debounceMs" INTEGER NOT NULL DEFAULT 50,"rollover" DECIMAL(20,6),"inputChannel" TEXT NOT NULL,"lastCounter" DECIMAL(20,6),"lastTimestamp" TIMESTAMP(3),CONSTRAINT "PulseConfig_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PulseConfig_deviceId_key" ON "PulseConfig"("deviceId"); CREATE UNIQUE INDEX "PulseConfig_deviceId_tenantId_key" ON "PulseConfig"("deviceId","tenantId"); CREATE INDEX "PulseConfig_tenantId_utility_idx" ON "PulseConfig"("tenantId","utility");
ALTER TABLE "PulseConfig" ADD CONSTRAINT "PulseConfig_deviceId_tenantId_fkey" FOREIGN KEY ("deviceId","tenantId") REFERENCES "Device"("id","tenantId") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "WirelessMeterConfig" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"deviceIdValue" TEXT NOT NULL,"manufacturerCode" TEXT NOT NULL,"encryptionKeyRef" TEXT,"securityMode" "SecurityMode" NOT NULL DEFAULT 'NONE',"rssi" INTEGER,"snr" DECIMAL(8,3),"receivedAt" TIMESTAMP(3),CONSTRAINT "WirelessMeterConfig_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WirelessMeterConfig_deviceId_key" ON "WirelessMeterConfig"("deviceId"); CREATE UNIQUE INDEX "WirelessMeterConfig_deviceId_tenantId_key" ON "WirelessMeterConfig"("deviceId","tenantId"); CREATE INDEX "WirelessMeterConfig_tenantId_deviceIdValue_idx" ON "WirelessMeterConfig"("tenantId","deviceIdValue");
ALTER TABLE "WirelessMeterConfig" ADD CONSTRAINT "WirelessMeterConfig_deviceId_tenantId_fkey" FOREIGN KEY ("deviceId","tenantId") REFERENCES "Device"("id","tenantId") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "MeterReplacement" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"oldMeterId" TEXT NOT NULL,"newMeterId" TEXT NOT NULL,"removedAt" TIMESTAMP(3) NOT NULL,"removedRegister" DECIMAL(20,6) NOT NULL,"installedAt" TIMESTAMP(3) NOT NULL,"installedRegister" DECIMAL(20,6) NOT NULL,"reason" TEXT NOT NULL,"documentation" TEXT,"actorId" TEXT NOT NULL,CONSTRAINT "MeterReplacement_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MeterReplacement_id_tenantId_key" ON "MeterReplacement"("id","tenantId"); CREATE INDEX "MeterReplacement_tenantId_oldMeterId_removedAt_idx" ON "MeterReplacement"("tenantId","oldMeterId","removedAt"); CREATE INDEX "MeterReplacement_tenantId_newMeterId_installedAt_idx" ON "MeterReplacement"("tenantId","newMeterId","installedAt");
ALTER TABLE "MeterReplacement" ADD CONSTRAINT "MeterReplacement_oldMeterId_tenantId_fkey" FOREIGN KEY ("oldMeterId","tenantId") REFERENCES "Meter"("id","tenantId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "MeterReplacement" ADD CONSTRAINT "MeterReplacement_newMeterId_tenantId_fkey" FOREIGN KEY ("newMeterId","tenantId") REFERENCES "Meter"("id","tenantId") ON DELETE RESTRICT ON UPDATE CASCADE;
